CREATE TABLE public.privacy_policies(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),partner_id uuid NOT NULL REFERENCES public.partners(id),location_id uuid REFERENCES public.locations(id),kind text NOT NULL CHECK(kind IN ('customer','request','screening','audit','notification','handoff','certificate')),version int NOT NULL,days int NOT NULL CHECK(days BETWEEN 1 AND 36500),effective_from timestamptz NOT NULL,effective_to timestamptz,status text NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','submitted','approved','rejected')),reason text NOT NULL,created_by uuid NOT NULL,reviewed_by uuid,created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.privacy_policies TO authenticated; GRANT ALL ON public.privacy_policies TO service_role; ALTER TABLE public.privacy_policies ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.privacy_requests(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),partner_id uuid NOT NULL REFERENCES public.partners(id),location_id uuid NOT NULL REFERENCES public.locations(id),patient_id uuid NOT NULL REFERENCES public.partner_customers(patient_id),kind text NOT NULL CHECK(kind IN ('access','export','correction','restriction','hold','release_hold','deletion','anonymization')),status text NOT NULL DEFAULT 'submitted' CHECK(status IN ('submitted','verified','approved','rejected','completed')),reason text NOT NULL,proposed_correction jsonb NOT NULL DEFAULT '{}',verification_method text,verified_by uuid,verified_at timestamptz,approved_by uuid,approved_at timestamptz,created_by uuid NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),completed_at timestamptz);
GRANT SELECT ON public.privacy_requests TO authenticated; GRANT ALL ON public.privacy_requests TO service_role; ALTER TABLE public.privacy_requests ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.privacy_controls(patient_id uuid PRIMARY KEY REFERENCES public.partner_customers(patient_id),partner_id uuid NOT NULL,location_id uuid NOT NULL,restricted boolean NOT NULL DEFAULT false,soft_deleted boolean NOT NULL DEFAULT false,anonymized boolean NOT NULL DEFAULT false,correction jsonb NOT NULL DEFAULT '{}',hold_type text CHECK(hold_type IN ('legal','clinical','maintenance')),hold_until timestamptz,request_id uuid REFERENCES public.privacy_requests(id),updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.privacy_controls TO authenticated; GRANT ALL ON public.privacy_controls TO service_role; ALTER TABLE public.privacy_controls ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.privacy_consent_events(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),patient_id uuid NOT NULL REFERENCES public.partner_customers(patient_id),partner_id uuid NOT NULL,location_id uuid NOT NULL,purpose text NOT NULL CHECK(purpose IN ('PRIVACY','TELEMEDICINE','NOTIFICATION')),policy_version text NOT NULL,state text NOT NULL CHECK(state IN ('granted','withdrawn')),actor_user_id uuid NOT NULL,source text NOT NULL CHECK(source IN ('customer_in_person','guardian_in_person','verified_request','legacy_record')),reason text NOT NULL,correlation_id uuid NOT NULL,created_at timestamptz NOT NULL DEFAULT clock_timestamp());
GRANT SELECT ON public.privacy_consent_events TO authenticated; GRANT ALL ON public.privacy_consent_events TO service_role; ALTER TABLE public.privacy_consent_events ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.privacy_events(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),partner_id uuid NOT NULL,location_id uuid,request_id uuid,policy_id uuid,actor_user_id uuid NOT NULL,action text NOT NULL,from_state text,to_state text,reason text NOT NULL,correlation_id uuid NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.privacy_events TO authenticated; GRANT ALL ON public.privacy_events TO service_role; ALTER TABLE public.privacy_events ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.privacy_operations(key uuid PRIMARY KEY,actor uuid NOT NULL,intent jsonb NOT NULL,result jsonb NOT NULL);
GRANT ALL ON public.privacy_operations TO service_role; ALTER TABLE public.privacy_operations ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.privacy_policies,public.privacy_requests,public.privacy_controls,public.privacy_consent_events,public.privacy_events,public.privacy_operations FROM PUBLIC,anon,authenticated;
GRANT SELECT ON public.privacy_policies,public.privacy_requests,public.privacy_controls,public.privacy_consent_events,public.privacy_events TO authenticated;
GRANT ALL ON public.privacy_policies,public.privacy_requests,public.privacy_controls,public.privacy_consent_events,public.privacy_events,public.privacy_operations TO service_role;
CREATE FUNCTION public.privacy_scope(_u uuid,_p uuid,_l uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT _u IS NOT NULL AND EXISTS(SELECT 1 FROM locations WHERE id=_l AND partner_id=_p) AND EXISTS(SELECT 1 FROM user_roles WHERE user_id=_u AND partner_id=_p AND role='OPERATIONS_ADMIN' AND status='ACTIVE') $$;
CREATE FUNCTION public.privacy_policy_scope(_u uuid,_p uuid,_l uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT _u IS NOT NULL AND partner_review_scope(_u,_p) AND (_l IS NULL OR EXISTS(SELECT 1 FROM locations WHERE id=_l AND partner_id=_p)) $$;
CREATE POLICY privacy_policy_read ON public.privacy_policies FOR SELECT TO authenticated USING(privacy_scope(auth.uid(),partner_id,location_id));
CREATE POLICY privacy_request_read ON public.privacy_requests FOR SELECT TO authenticated USING(privacy_scope(auth.uid(),partner_id,location_id));
CREATE POLICY privacy_control_read ON public.privacy_controls FOR SELECT TO authenticated USING(privacy_scope(auth.uid(),partner_id,location_id));
CREATE POLICY privacy_consent_read ON public.privacy_consent_events FOR SELECT TO authenticated USING(privacy_scope(auth.uid(),partner_id,location_id));
CREATE POLICY privacy_event_read ON public.privacy_events FOR SELECT TO authenticated USING(privacy_scope(auth.uid(),partner_id,location_id));
CREATE TRIGGER privacy_events_immutable BEFORE UPDATE OR DELETE ON public.privacy_events FOR EACH ROW EXECUTE FUNCTION public.care_immutable();
CREATE TRIGGER privacy_consents_immutable BEFORE UPDATE OR DELETE ON public.privacy_consent_events FOR EACH ROW EXECUTE FUNCTION public.care_immutable();
CREATE TRIGGER privacy_operations_immutable BEFORE UPDATE OR DELETE ON public.privacy_operations FOR EACH ROW EXECUTE FUNCTION public.care_immutable();
CREATE FUNCTION public.privacy_policy_guard() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF TG_OP='DELETE' OR OLD.status IN ('approved','rejected') OR (to_jsonb(NEW)-ARRAY['status','reviewed_by']) IS DISTINCT FROM (to_jsonb(OLD)-ARRAY['status','reviewed_by']) THEN RAISE EXCEPTION 'IMMUTABLE_POLICY_VERSION';END IF;RETURN NEW;END $$;
CREATE TRIGGER privacy_policy_immutable BEFORE UPDATE OR DELETE ON public.privacy_policies FOR EACH ROW EXECUTE FUNCTION public.privacy_policy_guard();
CREATE FUNCTION public.privacy_blocked(_patient uuid,_purpose text) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM privacy_controls WHERE patient_id=_patient AND (restricted OR soft_deleted OR anonymized)) OR EXISTS(SELECT 1 FROM (SELECT DISTINCT ON(purpose) purpose,state FROM privacy_consent_events WHERE patient_id=_patient AND purpose=ANY(CASE WHEN _purpose='NOTIFICATION' THEN ARRAY['PRIVACY','NOTIFICATION'] ELSE ARRAY['PRIVACY','TELEMEDICINE'] END) ORDER BY purpose,created_at DESC,id DESC)c WHERE state='withdrawn') $$;
CREATE FUNCTION public.privacy_future_request_guard() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN PERFORM 1 FROM partner_customers WHERE patient_id=NEW.patient_id FOR UPDATE; IF (TG_OP='INSERT' OR (NEW.state IS DISTINCT FROM OLD.state AND NEW.state IN ('submitted','queued','accepted','scheduled','in_consultation'))) AND privacy_blocked(NEW.patient_id,'TELEMEDICINE') THEN RAISE EXCEPTION 'PRIVACY_CONSENT_RESTRICTED';END IF;RETURN NEW;END $$;
CREATE TRIGGER privacy_request_gate BEFORE INSERT OR UPDATE ON public.consultation_requests FOR EACH ROW EXECUTE FUNCTION public.privacy_future_request_guard();
CREATE FUNCTION public.privacy_future_intake_guard() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN PERFORM 1 FROM partner_customers WHERE patient_id=NEW.patient_id FOR UPDATE; IF (TG_OP='INSERT' OR (NEW.status IS DISTINCT FROM OLD.status AND NEW.status IN ('CREATING','REQUESTED'))) AND privacy_blocked(NEW.patient_id,'TELEMEDICINE') THEN RAISE EXCEPTION 'PRIVACY_CONSENT_RESTRICTED';END IF;RETURN NEW;END $$;
CREATE TRIGGER privacy_intake_gate BEFORE INSERT OR UPDATE ON public.partner_intakes FOR EACH ROW EXECUTE FUNCTION public.privacy_future_intake_guard();
CREATE FUNCTION public.privacy_legacy_consent_capture() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE c partner_customers; BEGIN SELECT * INTO c FROM partner_customers WHERE patient_id=NEW.patient_id FOR UPDATE; IF c.patient_id IS NULL THEN RETURN NEW;END IF; IF NEW.accepted AND privacy_blocked(NEW.patient_id,'TELEMEDICINE') THEN RAISE EXCEPTION 'PRIVACY_CONSENT_RESTRICTED';END IF; INSERT INTO privacy_consent_events(patient_id,partner_id,location_id,purpose,policy_version,state,actor_user_id,source,reason,correlation_id) VALUES(c.patient_id,c.partner_id,c.location_id,NEW.consent_type,NEW.version,CASE WHEN NEW.accepted THEN 'granted' ELSE 'withdrawn' END,coalesce(auth.uid(),NEW.recorded_by),'legacy_record','Recorded consent event',gen_random_uuid());RETURN NEW;END $$;
CREATE TRIGGER privacy_legacy_consent AFTER INSERT ON public.patient_consents FOR EACH ROW WHEN(NEW.consent_type IN ('PRIVACY','TELEMEDICINE')) EXECUTE FUNCTION public.privacy_legacy_consent_capture();
CREATE FUNCTION public.privacy_notification_patient(_kind text,_id uuid) RETURNS uuid LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT patient_id FROM consultation_requests WHERE _kind='request' AND id=_id UNION ALL SELECT r.patient_id FROM care_certificates c JOIN consultation_requests r ON r.id=c.request_id WHERE _kind='certificate' AND c.id=_id UNION ALL SELECT r.patient_id FROM care_mcs_handoffs h JOIN consultation_requests r ON r.id=h.request_id WHERE _kind='handoff' AND h.id=_id LIMIT 1 $$;
CREATE FUNCTION public.privacy_notification_guard() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF privacy_blocked(privacy_notification_patient(NEW.source_kind,NEW.source_id),'NOTIFICATION') THEN RETURN NULL;END IF;RETURN NEW;END $$;
CREATE TRIGGER a_privacy_notification BEFORE INSERT ON public.operational_notifications FOR EACH ROW EXECUTE FUNCTION public.privacy_notification_guard();
CREATE POLICY privacy_notification_visibility ON public.operational_notifications AS RESTRICTIVE FOR SELECT TO authenticated USING(NOT privacy_blocked(privacy_notification_patient(source_kind,source_id),'NOTIFICATION'));
CREATE FUNCTION public.privacy_inventory(_u uuid) RETURNS TABLE(kind text,source_id uuid,partner_id uuid,location_id uuid,patient_id uuid,created_at timestamptz) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT 'customer',c.patient_id,c.partner_id,c.location_id,c.patient_id,c.created_at FROM partner_customers c WHERE privacy_scope(_u,c.partner_id,c.location_id) UNION ALL SELECT 'request',r.id,r.partner_id,r.location_id,r.patient_id,r.created_at FROM consultation_requests r WHERE privacy_scope(_u,r.partner_id,r.location_id) UNION ALL SELECT 'screening',i.id,i.partner_id,i.location_id,i.patient_id,i.evaluated_at FROM partner_intakes i WHERE privacy_scope(_u,i.partner_id,i.location_id) UNION ALL SELECT 'audit',a.id,a.partner_id,NULL::uuid,NULL::uuid,a.created_at FROM audit_log a WHERE EXISTS(SELECT 1 FROM user_roles WHERE user_id=_u AND role='OPERATIONS_ADMIN' AND partner_id=a.partner_id AND status='ACTIVE') UNION ALL SELECT 'notification',n.id,n.partner_id,n.location_id,privacy_notification_patient(n.source_kind,n.source_id),n.created_at FROM operational_notifications n WHERE privacy_scope(_u,n.partner_id,n.location_id) UNION ALL SELECT 'handoff',h.id,h.partner_id,h.location_id,r.patient_id,h.created_at FROM care_mcs_handoffs h JOIN consultation_requests r ON r.id=h.request_id WHERE privacy_scope(_u,h.partner_id,h.location_id) UNION ALL SELECT 'certificate',c.id,r.partner_id,r.location_id,r.patient_id,c.created_at FROM care_certificates c JOIN consultation_requests r ON r.id=c.request_id WHERE privacy_scope(_u,r.partner_id,r.location_id) $$;
CREATE FUNCTION public.privacy_retention(_u uuid) RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT coalesce(jsonb_agg(jsonb_build_object('kind',s.kind,'id',s.source_id,'partner_id',s.partner_id,'location_id',s.location_id,'policy_id',p.id,'version',p.version,'due_at',s.created_at+make_interval(days=>p.days),'days_remaining',ceil(extract(epoch FROM (s.created_at+make_interval(days=>p.days)-now()))/86400),'status',CASE WHEN c.hold_type IS NOT NULL AND (c.hold_until IS NULL OR c.hold_until>now()) THEN 'held' WHEN s.patient_id IS NULL AND EXISTS(SELECT 1 FROM privacy_controls hc WHERE hc.partner_id=s.partner_id AND hc.hold_type IS NOT NULL AND (hc.hold_until IS NULL OR hc.hold_until>now())) THEN 'held' WHEN EXISTS(SELECT 1 FROM operational_maintenance m WHERE m.partner_id=s.partner_id AND (m.location_id IS NULL OR m.location_id=s.location_id) AND now() BETWEEN m.starts_at AND m.ends_at) THEN 'maintenance' WHEN p.id IS NULL THEN 'unconfigured' WHEN s.created_at+make_interval(days=>p.days)<=now() THEN 'due_review' ELSE 'retained' END)),'[]') FROM (SELECT * FROM privacy_inventory(_u) ORDER BY created_at LIMIT 200)s LEFT JOIN privacy_controls c ON c.patient_id=s.patient_id LEFT JOIN LATERAL(SELECT * FROM privacy_policies p WHERE p.partner_id=s.partner_id AND p.kind=s.kind AND (p.location_id IS NULL OR p.location_id=s.location_id) AND p.status='approved' AND s.created_at>=p.effective_from AND (p.effective_to IS NULL OR s.created_at<p.effective_to) ORDER BY p.location_id NULLS LAST,p.version DESC LIMIT 1)p ON true $$;
CREATE FUNCTION public.privacy_center(_mode text DEFAULT 'admin') RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE u uuid:=auth.uid();BEGIN IF u IS NULL THEN RAISE EXCEPTION 'AUTH_REQUIRED';END IF; IF _mode='super' THEN IF NOT care_super(u) THEN RAISE EXCEPTION 'SUPER_REQUIRED';END IF;RETURN jsonb_build_object('totals',(SELECT coalesce(jsonb_agg(t),'[]') FROM(SELECT kind,status,count(*)::int count FROM privacy_requests GROUP BY kind,status)t),'policies',(SELECT count(*) FROM privacy_policies),'holds',(SELECT count(*) FROM privacy_controls WHERE hold_type IS NOT NULL),'withdrawals',(SELECT count(*) FROM privacy_consent_events WHERE state='withdrawn'),'rows','[]'::jsonb,'customers','[]'::jsonb,'consents','[]'::jsonb,'events','[]'::jsonb,'retention','[]'::jsonb);END IF; IF _mode<>'admin' OR NOT EXISTS(SELECT 1 FROM user_roles WHERE user_id=u AND role='OPERATIONS_ADMIN' AND partner_id IS NOT NULL AND status='ACTIVE') THEN RAISE EXCEPTION 'SCOPED_ADMIN_REQUIRED';END IF; RETURN jsonb_build_object('rows',(SELECT coalesce(jsonb_agg(r),'[]') FROM(SELECT id,partner_id,location_id,patient_id,kind,status,reason,proposed_correction,verification_method,created_at,verified_by,approved_by FROM privacy_requests WHERE privacy_scope(u,partner_id,location_id) ORDER BY created_at DESC LIMIT 100)r),'customers',(SELECT coalesce(jsonb_agg(c),'[]') FROM(SELECT c.patient_id id,c.partner_id,c.location_id,coalesce(p.restricted,false) restricted,coalesce(p.soft_deleted,false) soft_deleted,coalesce(p.anonymized,false) anonymized,p.hold_type FROM partner_customers c LEFT JOIN privacy_controls p USING(patient_id) WHERE privacy_scope(u,c.partner_id,c.location_id) ORDER BY c.created_at DESC LIMIT 100)c),'policies',(SELECT coalesce(jsonb_agg(p),'[]') FROM(SELECT id,partner_id,location_id,kind,version,days,effective_from,effective_to,status FROM privacy_policies WHERE privacy_policy_scope(u,partner_id,location_id) ORDER BY created_at DESC LIMIT 100)p),'consents',(SELECT coalesce(jsonb_agg(c),'[]') FROM(SELECT DISTINCT ON(patient_id,purpose) patient_id,purpose,state,policy_version,created_at,source FROM privacy_consent_events WHERE privacy_scope(u,partner_id,location_id) ORDER BY patient_id,purpose,created_at DESC,id DESC)c),'consent_history',(SELECT coalesce(jsonb_agg(c),'[]') FROM(SELECT patient_id,purpose,state,policy_version,created_at,source FROM privacy_consent_events WHERE privacy_scope(u,partner_id,location_id) ORDER BY created_at DESC LIMIT 200)c),'events',(SELECT coalesce(jsonb_agg(e),'[]') FROM(SELECT action,from_state,to_state,created_at,correlation_id FROM privacy_events WHERE privacy_scope(u,partner_id,location_id) ORDER BY created_at DESC LIMIT 200)e),'retention',privacy_retention(u));END $$;
CREATE FUNCTION public.privacy_command(_op text,_args jsonb,_key uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
#variable_conflict use_variable
DECLARE u uuid:=auth.uid();why text:=btrim(coalesce(_args->>'reason',''));p uuid;l uuid;id uuid:=(_args->>'id')::uuid;c partner_customers;r privacy_requests;pol privacy_policies;old text;result jsonb;prior privacy_operations;purpose text;v text;st text;ht text;
BEGIN
IF u IS NULL THEN RAISE EXCEPTION 'AUTH_REQUIRED';END IF;PERFORM care_require_strong();
IF _key IS NULL OR jsonb_typeof(_args) IS DISTINCT FROM 'object' OR length(_args::text)>3000 OR length(why) NOT BETWEEN 3 AND 500 OR EXISTS(SELECT 1 FROM jsonb_object_keys(_args)k WHERE k<>ALL(ARRAY['id','patient_id','partner_id','location_id','kind','reason','days','effective_from','effective_to','verification_method','purpose','policy_version','source','state','hold_type','hold_until','confirm','first_name','last_name','email','phone_number'])) THEN RAISE EXCEPTION 'INVALID_ARGUMENTS';END IF;
PERFORM pg_advisory_xact_lock(hashtextextended(_key::text,0)); SELECT * INTO prior FROM privacy_operations WHERE key=_key;
IF prior.key IS NOT NULL THEN IF NOT EXISTS(SELECT 1 FROM user_roles WHERE user_id=u AND status='ACTIVE' AND role IN ('OPERATIONS_ADMIN','SUPER_ADMIN')) THEN RAISE EXCEPTION 'SCOPED_ADMIN_REQUIRED';END IF;IF prior.actor<>u OR prior.intent<>jsonb_build_object('op',_op,'args',_args) THEN RAISE EXCEPTION 'IDEMPOTENCY_CONFLICT';END IF;IF _op LIKE 'policy_%' THEN SELECT * INTO pol FROM privacy_policies WHERE privacy_policies.id=coalesce((_args->>'id')::uuid,(prior.result->>'id')::uuid);IF NOT coalesce(privacy_policy_scope(u,pol.partner_id,pol.location_id),false) THEN RAISE EXCEPTION 'SCOPE_REQUIRED';END IF;ELSE SELECT * INTO c FROM partner_customers WHERE patient_id=coalesce((_args->>'patient_id')::uuid,(SELECT patient_id FROM privacy_requests WHERE privacy_requests.id=(_args->>'id')::uuid));IF NOT coalesce(privacy_scope(u,c.partner_id,c.location_id),false) THEN RAISE EXCEPTION 'SCOPED_ADMIN_REQUIRED';END IF;END IF;RETURN prior.result;END IF;
IF _op='policy_propose' THEN p:=(_args->>'partner_id')::uuid;l:=(_args->>'location_id')::uuid;IF NOT coalesce(privacy_policy_scope(u,p,l),false) THEN RAISE EXCEPTION 'SCOPE_REQUIRED';END IF;PERFORM 1 FROM partners WHERE partners.id=p FOR UPDATE;IF (_args->>'effective_from') IS NULL OR ((_args->>'effective_to') IS NOT NULL AND (_args->>'effective_to')::timestamptz<=(_args->>'effective_from')::timestamptz) THEN RAISE EXCEPTION 'INVALID_DATES';END IF;
INSERT INTO privacy_policies(partner_id,location_id,kind,version,days,effective_from,effective_to,reason,created_by) VALUES(p,l,_args->>'kind',coalesce((SELECT max(version)+1 FROM privacy_policies WHERE partner_id=p AND location_id IS NOT DISTINCT FROM l AND kind=_args->>'kind'),1),(_args->>'days')::int,(_args->>'effective_from')::timestamptz,(_args->>'effective_to')::timestamptz,why,u) RETURNING privacy_policies.id INTO id;st:='draft';
ELSIF _op IN ('policy_submit','policy_approve','policy_reject') THEN SELECT * INTO pol FROM privacy_policies WHERE privacy_policies.id=id FOR UPDATE;p:=pol.partner_id;l:=pol.location_id;old:=pol.status;IF NOT coalesce(privacy_policy_scope(u,p,l),false) THEN RAISE EXCEPTION 'SCOPE_REQUIRED';END IF;IF (_op='policy_submit' AND pol.status<>'draft') OR (_op<>'policy_submit' AND pol.status<>'submitted') THEN RAISE EXCEPTION 'INVALID_STATE';END IF;IF _op<>'policy_submit' AND pol.created_by=u THEN RAISE EXCEPTION 'INDEPENDENT_APPROVAL_REQUIRED';END IF;PERFORM 1 FROM partners WHERE partners.id=p FOR UPDATE;IF _op='policy_approve' AND EXISTS(SELECT 1 FROM privacy_policies x WHERE x.partner_id=p AND x.location_id IS NOT DISTINCT FROM l AND x.kind=pol.kind AND x.status='approved' AND tstzrange(x.effective_from,x.effective_to,'[)') && tstzrange(pol.effective_from,pol.effective_to,'[)')) THEN RAISE EXCEPTION 'OVERLAPPING_POLICY';END IF;st:=CASE _op WHEN 'policy_submit' THEN 'submitted' WHEN 'policy_approve' THEN 'approved' ELSE 'rejected' END;UPDATE privacy_policies SET status=st,reviewed_by=CASE WHEN _op='policy_submit' THEN NULL ELSE u END WHERE privacy_policies.id=id;
ELSIF _op IN ('request','consent') THEN SELECT * INTO c FROM partner_customers WHERE patient_id=(_args->>'patient_id')::uuid FOR UPDATE;p:=c.partner_id;l:=c.location_id;IF NOT coalesce(privacy_scope(u,p,l),false) THEN RAISE EXCEPTION 'SCOPED_ADMIN_REQUIRED';END IF;
IF _op='request' THEN IF _args->>'kind'='correction' AND (length(btrim(coalesce(_args->>'first_name',''))) NOT BETWEEN 1 AND 100 OR length(btrim(coalesce(_args->>'last_name',''))) NOT BETWEEN 1 AND 100 OR length(coalesce(_args->>'email',''))>255 OR length(coalesce(_args->>'phone_number',''))>40) THEN RAISE EXCEPTION 'INVALID_CORRECTION';END IF;INSERT INTO privacy_requests(partner_id,location_id,patient_id,kind,reason,created_by,proposed_correction) VALUES(p,l,c.patient_id,_args->>'kind',why,u,CASE WHEN _args->>'kind'='correction' THEN jsonb_build_object('first_name',btrim(_args->>'first_name'),'last_name',btrim(_args->>'last_name'),'email',_args->>'email','phone_number',_args->>'phone_number') ELSE '{}'::jsonb END) RETURNING privacy_requests.id INTO id;st:='submitted';
ELSE purpose:=_args->>'purpose';v:=btrim(coalesce(_args->>'policy_version',''));st:=_args->>'state';IF length(v) NOT BETWEEN 1 AND 100 OR _args->>'source' IS NULL OR _args->>'source' NOT IN ('customer_in_person','guardian_in_person','verified_request') OR st NOT IN ('granted','withdrawn') OR purpose NOT IN ('PRIVACY','TELEMEDICINE','NOTIFICATION') THEN RAISE EXCEPTION 'CONSENT_EVIDENCE_REQUIRED';END IF;IF st='granted' AND EXISTS(SELECT 1 FROM privacy_controls WHERE patient_id=c.patient_id AND (restricted OR soft_deleted OR anonymized)) THEN RAISE EXCEPTION 'RESTRICTED_CUSTOMER';END IF;INSERT INTO privacy_consent_events(patient_id,partner_id,location_id,purpose,policy_version,state,actor_user_id,source,reason,correlation_id) VALUES(c.patient_id,p,l,purpose,v,st,u,_args->>'source',why,_key) RETURNING privacy_consent_events.id INTO id;END IF;
ELSIF _op IN ('verify','approve','reject','execute','package') THEN SELECT * INTO r FROM privacy_requests WHERE privacy_requests.id=id FOR UPDATE;p:=r.partner_id;l:=r.location_id;old:=r.status;IF NOT coalesce(privacy_scope(u,p,l),false) THEN RAISE EXCEPTION 'SCOPED_ADMIN_REQUIRED';END IF;PERFORM 1 FROM partner_customers WHERE patient_id=r.patient_id FOR UPDATE;
IF _op='verify' THEN IF r.status<>'submitted' OR _args->>'verification_method' IS NULL OR _args->>'verification_method' NOT IN ('in_person','guardian_authority','existing_verified_channel') THEN RAISE EXCEPTION 'VERIFICATION_REQUIRED';END IF;st:='verified';UPDATE privacy_requests SET status=st,verification_method=_args->>'verification_method',verified_by=u,verified_at=now() WHERE privacy_requests.id=id;
ELSIF _op='approve' THEN IF r.status<>'verified' OR r.verified_by=u OR r.created_by=u THEN RAISE EXCEPTION 'INDEPENDENT_APPROVAL_REQUIRED';END IF;st:='approved';UPDATE privacy_requests SET status=st,approved_by=u,approved_at=now() WHERE privacy_requests.id=id;
ELSIF _op='reject' THEN IF r.status NOT IN ('submitted','verified') THEN RAISE EXCEPTION 'INVALID_STATE';END IF;st:='rejected';UPDATE privacy_requests SET status=st WHERE privacy_requests.id=id;
ELSIF _op='package' THEN IF r.status NOT IN ('approved','completed') OR r.kind NOT IN ('access','export') THEN RAISE EXCEPTION 'APPROVED_EXPORT_REQUIRED';END IF;result:=jsonb_build_object('schema_version',1,'request_id',r.id,'generated_at',now(),'customer',jsonb_build_object('reference',r.patient_id),'requests',(SELECT coalesce(jsonb_agg(x),'[]') FROM(SELECT state,created_at,updated_at FROM consultation_requests WHERE patient_id=r.patient_id AND partner_id=p ORDER BY created_at LIMIT 100)x),'consents',(SELECT coalesce(jsonb_agg(x),'[]') FROM(SELECT purpose,policy_version,state,created_at FROM privacy_consent_events WHERE patient_id=r.patient_id AND partner_id=p ORDER BY created_at LIMIT 100)x),'certificates',(SELECT coalesce(jsonb_agg(x),'[]') FROM(SELECT cert.state,cert.created_at FROM care_certificates cert JOIN consultation_requests cr ON cr.id=cert.request_id WHERE cr.patient_id=r.patient_id AND cr.partner_id=p ORDER BY cert.created_at LIMIT 100)x),'files_included',false,'clinical_content_included',false);st:='completed';UPDATE privacy_requests SET status=st,completed_at=coalesce(completed_at,now()) WHERE privacy_requests.id=id;
ELSE IF r.status<>'approved' OR _args->>'confirm' IS DISTINCT FROM 'APPROVED_ACTION' THEN RAISE EXCEPTION 'APPROVED_CONFIRMATION_REQUIRED';END IF;IF r.kind IN ('deletion','anonymization') AND EXISTS(SELECT 1 FROM privacy_controls WHERE patient_id=r.patient_id AND hold_type IS NOT NULL AND (hold_until IS NULL OR hold_until>now())) THEN RAISE EXCEPTION 'ACTIVE_HOLD';END IF;IF r.kind IN ('access','export') THEN RAISE EXCEPTION 'SPECIALIST_ACTION_REQUIRED';END IF;IF r.kind='hold' AND EXISTS(SELECT 1 FROM privacy_controls WHERE patient_id=r.patient_id AND hold_type IS NOT NULL AND (hold_until IS NULL OR hold_until>now())) THEN RAISE EXCEPTION 'ACTIVE_HOLD_REQUIRES_RELEASE';END IF;ht:=_args->>'hold_type';IF r.kind='hold' AND (ht IS NULL OR ht NOT IN ('legal','clinical','maintenance') OR (_args->>'hold_until' IS NOT NULL AND (_args->>'hold_until')::timestamptz<=now())) THEN RAISE EXCEPTION 'HOLD_EVIDENCE_REQUIRED';END IF;
INSERT INTO privacy_controls(patient_id,partner_id,location_id,restricted,soft_deleted,anonymized,correction,hold_type,hold_until,request_id) VALUES(r.patient_id,p,l,r.kind IN ('restriction','deletion','anonymization'),r.kind='deletion',r.kind='anonymization',CASE WHEN r.kind='correction' THEN r.proposed_correction ELSE '{}'::jsonb END,CASE WHEN r.kind='hold' THEN ht END,CASE WHEN r.kind='hold' THEN (_args->>'hold_until')::timestamptz END,r.id) ON CONFLICT(patient_id) DO UPDATE SET restricted=privacy_controls.restricted OR EXCLUDED.restricted,soft_deleted=privacy_controls.soft_deleted OR EXCLUDED.soft_deleted,anonymized=privacy_controls.anonymized OR EXCLUDED.anonymized,correction=CASE WHEN r.kind='correction' THEN EXCLUDED.correction ELSE privacy_controls.correction END,hold_type=CASE WHEN r.kind='release_hold' THEN NULL WHEN r.kind='hold' THEN EXCLUDED.hold_type ELSE privacy_controls.hold_type END,hold_until=CASE WHEN r.kind='release_hold' THEN NULL WHEN r.kind='hold' THEN EXCLUDED.hold_until ELSE privacy_controls.hold_until END,request_id=r.id,updated_at=now();st:='completed';UPDATE privacy_requests SET status=st,completed_at=now() WHERE privacy_requests.id=id;END IF;
ELSE RAISE EXCEPTION 'UNKNOWN_OPERATION';END IF;
INSERT INTO privacy_events(partner_id,location_id,request_id,policy_id,actor_user_id,action,from_state,to_state,reason,correlation_id) VALUES(p,l,CASE WHEN _op NOT LIKE 'policy_%' AND _op<>'consent' THEN id END,CASE WHEN _op LIKE 'policy_%' THEN id END,u,_op,old,st,why,_key);result:=coalesce(result,jsonb_build_object('id',id,'status',st));INSERT INTO privacy_operations VALUES(_key,u,jsonb_build_object('op',_op,'args',_args),result);RETURN result;
END $$;
REVOKE ALL ON FUNCTION public.privacy_scope(uuid,uuid,uuid),public.privacy_policy_scope(uuid,uuid,uuid),public.privacy_blocked(uuid,text),public.privacy_future_request_guard(),public.privacy_future_intake_guard(),public.privacy_legacy_consent_capture(),public.privacy_notification_patient(text,uuid),public.privacy_notification_guard(),public.privacy_inventory(uuid),public.privacy_retention(uuid),public.privacy_center(text),public.privacy_command(text,jsonb,uuid),public.privacy_policy_guard() FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.privacy_scope(uuid,uuid,uuid),public.privacy_blocked(uuid,text),public.privacy_notification_patient(text,uuid),public.privacy_center(text),public.privacy_command(text,jsonb,uuid) TO authenticated;
CREATE OR REPLACE FUNCTION public.notification_source_access(_kind text,_id uuid,_p uuid,_l uuid,_u uuid) RETURNS boolean LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ BEGIN IF _u IS NULL OR privacy_blocked(privacy_notification_patient(_kind,_id),'NOTIFICATION') THEN RETURN false; END IF; IF _kind='application' THEN RETURN partner_application_access(_id,_u); END IF; IF _kind='request' THEN RETURN consultation_request_access(_id,_u); END IF; IF _kind='certificate' THEN RETURN certificate_read(_id,_u); END IF; IF _kind='handoff' THEN RETURN EXISTS(SELECT 1 FROM care_mcs_handoffs h WHERE h.id=_id AND (notification_admin(_u,h.partner_id) OR partner_customer_write(_u,h.partner_id,h.location_id))); END IF; IF _kind IN ('doctor','assignment') THEN RETURN notification_admin(_u,_p) OR EXISTS(SELECT 1 FROM doctors d LEFT JOIN doctor_assignments a ON a.doctor_id=d.id WHERE d.auth_user_id=_u AND ((_kind='doctor' AND d.id=_id) OR (_kind='assignment' AND a.id=_id)) AND EXISTS(SELECT 1 FROM user_roles r WHERE r.user_id=_u AND r.role='DOCTOR' AND r.status='ACTIVE')); END IF; RETURN notification_admin(_u,_p); END $$;
CREATE FUNCTION public.privacy_identity_visible(_patient uuid,_u uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT NOT EXISTS(SELECT 1 FROM privacy_controls c WHERE c.patient_id=_patient AND (c.soft_deleted OR c.anonymized)) OR EXISTS(SELECT 1 FROM partner_customers c WHERE c.patient_id=_patient AND privacy_scope(_u,c.partner_id,c.location_id)) $$;
REVOKE ALL ON FUNCTION public.privacy_identity_visible(uuid,uuid) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.privacy_identity_visible(uuid,uuid) TO authenticated;
CREATE POLICY privacy_identity_read ON public.patients AS RESTRICTIVE FOR SELECT TO authenticated USING(privacy_identity_visible(id,auth.uid()));
CREATE FUNCTION public.privacy_identity_write_guard() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF EXISTS(SELECT 1 FROM privacy_controls WHERE patient_id=NEW.id AND (restricted OR soft_deleted OR anonymized)) THEN RAISE EXCEPTION 'RESTRICTED_CUSTOMER'; END IF; RETURN NEW; END $$;
CREATE TRIGGER privacy_identity_write BEFORE UPDATE ON public.patients FOR EACH ROW EXECUTE FUNCTION public.privacy_identity_write_guard();
REVOKE ALL ON FUNCTION public.privacy_identity_write_guard() FROM PUBLIC,anon,authenticated;
CREATE FUNCTION public.privacy_customer_display(_patient uuid) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE c privacy_controls; p patients; BEGIN IF NOT partner_customer_read(_patient,auth.uid()) THEN RAISE EXCEPTION 'CUSTOMER_SCOPE_REQUIRED';END IF;SELECT * INTO c FROM privacy_controls WHERE patient_id=_patient;SELECT * INTO p FROM patients WHERE id=_patient;IF c.soft_deleted OR c.anonymized THEN RETURN jsonb_build_object('id',_patient,'first_name','Restricted','last_name','record','email',NULL,'phone_number',NULL,'restricted',true);END IF;RETURN jsonb_build_object('id',_patient,'first_name',coalesce(c.correction->>'first_name',p.first_name),'last_name',coalesce(c.correction->>'last_name',p.last_name),'email',coalesce(c.correction->>'email',p.email),'phone_number',coalesce(c.correction->>'phone_number',p.phone_number),'restricted',coalesce(c.restricted,false));END $$;
REVOKE ALL ON FUNCTION public.privacy_customer_display(uuid) FROM PUBLIC,anon;GRANT EXECUTE ON FUNCTION public.privacy_customer_display(uuid) TO authenticated;
CREATE FUNCTION public.privacy_legacy_history_guard() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF partner_customer_enrolled(OLD.patient_id) THEN RAISE EXCEPTION 'IMMUTABLE_CONSENT_HISTORY'; END IF;IF TG_OP='DELETE' THEN RETURN OLD; END IF;RETURN NEW;END $$;
CREATE TRIGGER privacy_legacy_history BEFORE UPDATE OR DELETE ON public.patient_consents FOR EACH ROW EXECUTE FUNCTION public.privacy_legacy_history_guard();
REVOKE ALL ON FUNCTION public.privacy_legacy_history_guard() FROM PUBLIC,anon,authenticated;